import{_ as a}from"./chunks/panneau-daimon.Dp4VEGF4.js";import{_ as t,o,c as r,a2 as n}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Modèle mental","description":"","frontmatter":{"title":"Modèle mental"},"headers":[],"relativePath":"guide/modele-mental.md","filePath":"guide/modele-mental.md"}'),i={name:"guide/modele-mental.md"};function s(l,e,d,c,u,p){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="modele-mental" tabindex="-1">Modèle mental <a class="header-anchor" href="#modele-mental" aria-label="Permalink to &quot;Modèle mental&quot;">​</a></h1><p>Daimon est un outil, pas un assistant. Votre client IA l&#39;interroge ; Daimon perçoit ou agit, puis répond. Il n&#39;appelle aucun modèle d&#39;IA et n&#39;agit jamais de sa propre initiative.</p><h2 id="les-organes" tabindex="-1">Les organes <a class="header-anchor" href="#les-organes" aria-label="Permalink to &quot;Les organes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Organe</th><th>Rôle</th><th>Outils</th><th>Référence</th></tr></thead><tbody><tr><td><strong>Vue</strong></td><td>Perception visuelle : captures d&#39;un écran, localisation d&#39;un texte (OCR sur l&#39;appareil : Apple Vision sous macOS, OCR de Windows sous Windows), géométrie des écrans, calibration</td><td><code>vue_*</code></td><td><a href="/Daimon/reference/vue.html">Vue</a></td></tr><tr><td><strong>Touché</strong></td><td>Arbre d&#39;accessibilité d&#39;une fenêtre (accessibilité macOS, UI Automation sous Windows), ou élément situé sous un point</td><td><code>touche_*</code></td><td><a href="/Daimon/reference/touche.html">Touché</a></td></tr><tr><td><strong>Mains</strong></td><td>Action : cliquer, saisir, appuyer, glisser, naviguer, combinaisons de touches, fenêtres et applications</td><td><code>main_*</code></td><td><a href="/Daimon/reference/mains.html">Mains</a></td></tr><tr><td><strong>Overlay</strong></td><td>Repères à l&#39;écran : surbrillance, projecteur, halo de curseur, bandeau</td><td><code>overlay_*</code></td><td><a href="/Daimon/reference/overlay.html">Overlay</a></td></tr><tr><td><strong>Face</strong></td><td>L&#39;application elle-même : icône, panneau, parcours d&#39;installation</td><td>aucun</td><td>cette page</td></tr></tbody></table><h2 id="le-panneau" tabindex="-1">Le panneau <a class="header-anchor" href="#le-panneau" aria-label="Permalink to &quot;Le panneau&quot;">​</a></h2><p>Un clic sur l&#39;icône de Daimon ouvre le panneau. Il porte :</p><ul><li>le <strong>curseur de plafond</strong> des Mains ;</li><li>les <strong>clients IA</strong>, avec un interrupteur par client ;</li><li>les <strong>mises à jour</strong> ;</li><li>le <strong>journal d&#39;activité</strong>, dont le bouton ouvre le dossier ;</li><li>le réglage <strong>Présence à l&#39;écran</strong>, qui active l&#39;Overlay ;</li><li><strong>Ouvrir le dossier de configuration</strong>.</li></ul><p><img src="'+a+'" alt="Le panneau Daimon : autorisations accordées, clients IA, curseur de plafond des Mains, présence à l&#39;écran"></p><p><em>Le panneau de Daimon sous macOS, capturé par Daimon lui-même. Le plafond y est réglé sur L4 (autonomie), d&#39;où le bouton rouge « Désengager l&#39;autonomie L4 ».</em></p><h2 id="percevoir-puis-agir" tabindex="-1">Percevoir, puis agir <a class="header-anchor" href="#percevoir-puis-agir" aria-label="Permalink to &quot;Percevoir, puis agir&quot;">​</a></h2><p>Un échange typique : l&#39;IA regarde (Vue ou Touché), décide, puis agit (Mains), et peut montrer ce qu&#39;elle fait (Overlay). Chaque action des Mains a un niveau, et le plafond que vous fixez refuse tout ce qui le dépasse : voir <a href="./plafond-et-exclusions.html">Plafond et exclusions</a>.</p><h2 id="l-overlay-est-desactive-par-defaut" tabindex="-1">L&#39;Overlay est désactivé par défaut <a class="header-anchor" href="#l-overlay-est-desactive-par-defaut" aria-label="Permalink to &quot;L&#39;Overlay est désactivé par défaut&quot;">​</a></h2><p>Les outils <code>overlay_*</code> répondent toujours <code>ok</code>, même si aucune fenêtre d&#39;overlay n&#39;est en cours d&#39;exécution : l&#39;ordre est alors abandonné. Activez <strong>Présence à l&#39;écran</strong> dans le panneau pour voir les repères. Un processus à part, le helper, les dessine ; <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> dit s&#39;il vit (clé <code>overlay</code>).</p><h2 id="diagnostic" tabindex="-1">Diagnostic <a class="header-anchor" href="#diagnostic" aria-label="Permalink to &quot;Diagnostic&quot;">​</a></h2><p><a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> donne en un appel l&#39;état des autorisations, leurs conséquences et le plafond actif.</p>',15)])])}const f=t(i,[["render",s]]);export{g as __pageData,f as default};
